<template><view v-if="loading&&!count" class="skeleton-list"><view v-for="n in 3" :key="n" class="skeleton" /></view><view v-else-if="error" class="state-view"><AppIcon class="app-icon" name="wifi" :size="40" /><text class="state-title">暂时没能加载</text><text class="muted">{{error}}</text><button class="ui-button btn outline" @click="$emit('retry')">重新加载</button></view><view v-else-if="!count" class="state-view"><AppIcon class="app-icon" :name="icon" :size="44" /><text class="state-title">{{title}}</text><text class="muted">{{description}}</text><slot /></view></template>
<script setup>import AppIcon from './AppIcon.vue';defineProps({loading:Boolean,error:String,count:Number,icon:{type:String,default:'box'},title:{type:String,default:'这里还没有内容'},description:{type:String,default:'可以先去市场看看喜欢的服务'}});defineEmits(['retry'])</script>
